/** Un pictogramme en SVG (24 × 24, tracé de la couleur du texte). Nom inconnu : chaîne vide. */
function icone(string $nom, string $classe = ''): string
{
    if (!isset(ICONES[$nom])) return '';
    return '<svg class="icone' . ($classe !== '' ? ' ' . e($classe) : '') . '" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'
        . ICONES[$nom] . '</svg>';
}
